 {"path": "characters.json", "content": "{
"main_characters": [
{
"name": "林烈",
"role": "protagonist",
"identity": "退伍军人，野外生存专家，曾服役于西南边防某部",
"traits": ["沉稳可靠", "行动力强", "不善言辞", "内心孤独", "害怕被抛弃"],
"overt_motivation": "找到二十年前失踪父亲的下落，查明当年探险队的真相",
"covert_motivation": "证明自己不只是'只会打仗的莽夫'，在和平年代找到存在的意义",
"secret_fear": "害怕自己像父亲一样消失在大山深处，再也回不来，害怕被这个世界遗忘",
"misperception_of_other": "起初认为沈书白是'只会纸上谈兵的书呆子'，不相信他能在野外生存",
"hidden_connection": "父亲当年的探险队中，有一位成员是沈书白父亲的学生"
},
{
"name": "沈书白",
"role": "deuteragonist",
"identity": "考古系研究生，古文字与南诏史专家，导师是国内南诏研究权威",
"traits": ["聪明博学", "学术傲气", "内心脆弱", "害怕失败", "渴望被认可"],
"overt_motivation": "解开唐代铜牌拓片背后的南诏古城之谜，完成导师托付的研究",
"covert_motivation": "证明自己的学术价值，不辜负父亲的期望，找到属于自己的人生方向",
"secret_fear": "害怕自己的研究从根上就是错的，害怕让所有信任自己的人失望",
"misperception_of_other": "起初认为林烈是'头脑简单四肢发达的粗人'，不相信他能理解历史的价值",
"hidden_connection": "父亲生前最后一篇论文的合作者，正是林烈父亲探险队中的一员"
}
],
"supporting_characters": [
{
"name": "阿朵",
"function": "助力",
"identity": "横断山脉深处某村寨的年轻向导，熟悉山区地形和各村寨关系",
"description": "二十出头的彝族姑娘，父母早年外出打工，由祖母抚养长大。性格开朗但心思细腻，对大山有深厚感情，对外来者既好奇又警惕。"
},
{
"name": "老陈",
"function": "反转点",
"identity": "当年探险队成员之一，现隐居在山区某个偏远村寨",
"description": "六十多岁的老人，当年是探险队的后勤人员，是唯一知道部分真相的幸存者。性格沉默寡言，内心背负着沉重的愧疚。"
},
{
"name": "黑三",
"function": "阻碍",
"identity": "活跃在西南边境的文物走私团伙头目",
"description": "四十岁左右，心狠手辣，在道上有一定势力。多年来一直在寻找南诏古城的下落，当年曾与林烈父亲的探险队有过接触。"
}
],
"relationship_dynamics": "林烈与沈书白从互相看不顺眼的'文武对立'开始，在共同经历生死考验后逐渐理解对方的价值。两人的关系经历三个阶段：初期的互相质疑和争吵（因专业背景和性格差异产生摩擦）→ 中期的被迫合作与 grudging respect（在危机中发现对方的不可替代性）→后期的生死托付与真正信任（关键时刻互相救命，建立深厚情谊）。阿朵作为向导和调解者，在两人关系中起到润滑剂作用。老陈的出现揭示了父辈之间的隐秘联系，让两人意识到他们的相遇并非偶然。黑三的追杀则成为两人关系的催化剂，迫使他们放下成见，真正成为可以托付后背的伙伴。"
}
"}

